CREATE TABLE public.dokploy_connections (user_id uuid PRIMARY KEY, endpoint text NOT NULL, encrypted_api_key text NOT NULL, account_label text NOT NULL DEFAULT 'Dokploy', verified_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.dokploy_connections TO service_role; ALTER TABLE public.dokploy_connections ENABLE ROW LEVEL SECURITY; COMMENT ON TABLE public.dokploy_connections IS 'Server-only encrypted credentials. Authenticated handlers explicitly scope every access to the verified user_id. No browser grants or policies.';